"use client";

import "./form.css";

import type React from "react";

import { Form as BaseForm } from "@base-ui/react/form";
import { cn } from "tailwind-variants";

import { FormContext, useFormContext } from "./form.context";
import { formVariants, type FormVariants } from "./form.variants";

export type FormProps = FormVariants & React.ComponentProps<typeof BaseForm>;

export const FormRoot = ({ children, className, layout, ...props }: FormProps) => {
  const slots = formVariants({ layout });

  return (
    <FormContext.Provider value={{ slots }}>
      <BaseForm className={cn(slots.root(), className)} {...props}>
        {children}
      </BaseForm>
    </FormContext.Provider>
  );
};

/* eslint-disable perfectionist/sort-objects */

import { tv, type VariantProps } from "tailwind-variants";

export const formVariants = tv({
  slots: {
    root: "form",
  },
  variants: {
    layout: {
      vertical: {
        root: "form--vertical",
      },
      horizontal: {
        root: "form--horizontal",
      },
    },
  },
  defaultVariants: {
    layout: "vertical",
  },
});

export type FormVariants = VariantProps<typeof formVariants>;

"use client";

import { createContext, useContext } from "react";

import { formVariants } from "./form.variants";

export type FormContext = {
  slots: ReturnType<typeof formVariants>;
};

export const FormContext = createContext<FormContext | null>(null);

export const useFormContext = () => {
  const context = useContext(FormContext);
  return context ?? { slots: formVariants() };
};

.form {
  @apply flex w-full flex-col gap-4 text-foreground;
}

.form--vertical {
  @apply flex-col;
}

.form--horizontal {
  @apply flex-row items-start flex-wrap;
}

import { FormRoot } from "./form";

export const Form = {
  Root: FormRoot,
};

export { FormRoot };

export type { FormProps } from "./form";
export { FormContext, useFormContext } from "./form.context";
export { type FormVariants, formVariants } from "./form.variants";
